/** autogenerated **/
Ext._define('rh.teletrabalho.Manage', {
    extend: 'toolkit.widget.TabPanel',

    plan: function(value, dispatch){
		dispatch = core.nullValue(dispatch, true);
		if(value !== undefined){
			this._plan = value;

			if(dispatch) this.observePlan();
		}
		return this._plan;
	},

    observePlan: function() {
		if(this.plan()){
			this.getMarkTeleWorkGrid().enable();
			this.getMarkTeleWorkGrid().setParam('mark_plan__mov_teletrabalho', this.plan().pk);
			this.getMarkTeleWorkGrid().setParam('servidor_pk', this.plan().servidor);
			this.getMarkTeleWorkGrid().setFilterProperty('mark_plan__mov_teletrabalho', this.plan().pk, 1000);
		}
		else{
			this.getMarkTeleWorkGrid().disable();
			this.getMarkTeleWorkGrid().getStore().removeAll();
			this.getMarkTeleWorkGrid().setFilterProperty('mark_plan__mov_teletrabalho', 0, 1000, false);
            this.getDetalheMetaGrid().disable();
			this.getDetalheMetaGrid().getStore().removeAll();
			this.getDetalheMetaGrid().setFilterProperty('request__pk', 0, 1000, false);
		}
	},

    getPlanGrid: function(cfg) {
        if(!this._planGrid) {
            this._planGrid = Ext._create('rh.teletrabalho.Grid', {
                title: 'Planos',
                region: 'north',
                split: true,
                height: 300,
            });

            this._planGrid.getSelectionModel().on({
				scope: this,
				rowselect: function(grid, index, record) {
					this.plan(record.data);
				},
				rowdeselect: function(grid, index, record){
					this.plan(null);
				}
			});

			this._planGrid.getStore().on({
                scope: this,
                beforeload: function(st, options){
					rec = this._planGrid.getSelectionModel().getSelected();
					this._planGrid._lastEvent = rec? rec.data.pk: null;
				},
				load: function(st, records, options){
					if(!records.length)
						this.plan(null);
				}
            });
        }

        return this._planGrid;
    },

    observeMark: function(requestId) {
		if(requestId != null){
			this.getDetalheMetaGrid().enable();
			this.getDetalheMetaGrid().setParam('request__pk', requestId);
			this.getDetalheMetaGrid().setFilterProperty('request__pk', requestId, 1000, true);
		}
		else{
			this.getDetalheMetaGrid().disable();
			this.getDetalheMetaGrid().getStore().removeAll();
			this.getDetalheMetaGrid().setFilterProperty('request__pk', 0, 1000, false);
		}
	},

    getMarkTeleWorkGrid: function(cfg) {
		if(!this._markTeleWorkGrid){
			this._markTeleWorkGrid = Ext._create('rh.teletrabalho.mark_telework.Grid', {
                title: '.. Metas',
				region: 'center',
				gridAutoLoad: false,
				disabled: true,
				height: 400,
                hideActions: ['edit', 'remove', 'copy'],
                configOrderToolBar: ['search'],
			});

            this._markTeleWorkGrid.getSelectionModel().on({
				scope: this,
                rowselect: function (sm, index, record) {
                    this.observeMark(record.get('request'));
                },
                rowdeselect: function (sm) {
                    this.observeMark(null);
                }
			});
        }

		return this._markTeleWorkGrid;
	},

    getDetalheMetaGrid: function(cfg) {
		if(!this._detalheMetaGrid)
			this._detalheMetaGrid = Ext._create('rh.teletrabalho.detalhe_meta.Grid', {
                title: 'Detalhes da Meta',
                region: 'east',
				gridAutoLoad: false,
				disabled: true,
				split: true,
                width: "50%",
				height: 400,
                hideActions: ['edit', 'remove', 'copy'],
                configOrderToolBar: [],
			});

		return this._detalheMetaGrid;
	},

    getControlPanel: function () {
        if (!this._controlPanel)
            this._controlPanel = Ext._create('Ext.Panel', {
                width: 15,
                frame: true,
                layout: 'vbox',
                bodyStyle: {
                    'border-top': 0,
                    'border-bottom': 0
                },
            });
        return this._controlPanel;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Gestor Teletrabalho'
            }
        );

        Ext.apply(
            cfg,
            {
				region: 'center',
                layout: 'border',
                border: false,
                scope: this,
                items: [
                    this.getPlanGrid(cfg),
                    {
                        region: 'center',
                        layout: 'border',
                        minHeight: 150,
                        scope: this,
                        bodyStyle: {
                            'border-left': 0,
                            'border-right': 0
                        },
                        layoutConfig: {
                            align: 'stretch'
                        },
                        items: [
                            this.getMarkTeleWorkGrid(cfg),
                            this.getControlPanel(),
                            this.getDetalheMetaGrid(cfg),
                        ]
                    }
                ],
			}
        );

        rh.teletrabalho.Manage.superclass.constructor.call(this, cfg);
        this.observePlan();
    }
});

